v=0; for f in $( { git diff HEAD --diff-filter=A --name-only; git ls-files --others --exclude-standard; } | grep '\.java$' | sort -u ); do [ -f "$f" ] || continue; grep -q '@author AI-generated' "$f" && grep -q '@author Xceptance GmbH 2026' "$f" || v=1; done; { git diff HEAD -U0 -- '*.java'; for f in $(git ls-files --others --exclude-standard | grep '\.java$'); do sed 's/^/+/' "$f"; done; } | grep -E '^\+' | grep -v '^+++' | grep -qE '//[[:space:]]*AI-generated' && v=1; [ $v = 1 ] && echo VIOLATED || echo OBEYED
